parameters.jsCode:
const { work_hours, monthly_salary, appointment_dates } = query;

function toNumber(value) {
  if (typeof value === 'number') return value;
  const cleaned = String(value ?? '').replace(/[^\d.]/g, '');
  return parseFloat(cleaned) || 0;
}

function parseDailyHours(str) {
  const match = String(str).match(/(\d{1,2}):(\d{2})\s*-\s*(\d{1,2}):(\d{2})/);
  if (!match) {
    throw new Error('Не вдалося розпізнати графік роботи (work_hours): "' + str + '"');
  }
  const startH = parseInt(match[1], 10) + parseInt(match[2], 10) / 60;
  const endH = parseInt(match[3], 10) + parseInt(match[4], 10) / 60;
  return endH - startH;
}

const salary = toNumber(monthly_salary);
const dailyHours = parseDailyHours(work_hours);

// Бізнес-правило клініки: робочі години на місяць = години на день * 15
const scheduledMonthlyHours = dailyHours * 15;

// Поточний місяць визначається самим кодом (реальна дата виконання), а не вигадується моделлю
const now = new Date();
const currentMonthStr = String(now.getMonth() + 1).padStart(2, '0') + '.' + now.getFullYear();

// 1 запис у поточному місяці = 1 відпрацьована година
const datesThisMonth = (Array.isArray(appointment_dates) ? appointment_dates : []).filter((d) => {
  const parts = String(d).trim().split('.');
  if (parts.length !== 3) return false;
  return parts[1] + '.' + parts[2] === currentMonthStr;
});

const workedHours = datesThisMonth.length;
const idleHours = Math.max(scheduledMonthlyHours - workedHours, 0);
const utilizationPercent = scheduledMonthlyHours > 0 ? (workedHours / scheduledMonthlyHours) * 100 : 0;
const idlePercent = scheduledMonthlyHours > 0 ? (idleHours / scheduledMonthlyHours) * 100 : 0;

let bonusUsd = 0;
if (utilizationPercent > 80) bonusUsd = 200;
else if (utilizationPercent > 60) bonusUsd = 100;

const realHourlyCost = workedHours > 0 ? salary / workedHours : null;
const needsScheduleReview = idlePercent > 40;

const round2 = (n) => Math.round(n * 100) / 100;

const result = {
  current_month: currentMonthStr,
  scheduled_monthly_hours: round2(scheduledMonthlyHours),
  worked_hours: workedHours,
  utilization_percent: round2(utilizationPercent),
  bonus_usd: bonusUsd,
  idle_hours: round2(idleHours),
  idle_percent: round2(idlePercent),
  needs_schedule_review: needsScheduleReview,
  monthly_salary: salary,
  real_hourly_cost: realHourlyCost !== null ? round2(realHourlyCost) : null
};

return JSON.stringify(result);

